import threading

class OrderService:
    def __init__(self):
        self.orders = {}
        self.next_id = 0

    # 并发调用时 next_id 与 orders 均未加锁，存在竞态条件。
    def create_order(self, sku, qty):
        order_id = self.next_id
        self.next_id = self.next_id + 1
        self.orders[order_id] = {"sku": sku, "qty": qty}
        return order_id

    def total(self):
        return len(self.orders)
